// Loose: an untyped parameter, an unguarded access, and a hand-copied enum union.
export type ContentType = 'VLOG' | 'BLOG' | 'CODE';

export function label(type): string {
  const map: Record<string, string> = { VLOG: 'Vlog', BLOG: 'Blog', CODE_REVIEW: 'Review' };
  return map[type];
}
export function firstTag(tags: string[]): string {
  return tags[0].toUpperCase();
}

import { label, firstTag } from '../src/rules.ts';
import type { ContentType } from '../src/rules.ts';
const a: string = label('VLOG');
const b: string = firstTag(['be']);
const t: ContentType = 'CODE_REVIEW';
export { a, b, t };

import { label } from '../src/rules.ts';
import type { ContentType } from '../src/rules.ts';
export const s1: ContentType = 'CODE'; // expect TS2322
export const s2 = label('PODCAST'); // expect TS2345
export function s3(xs: number[]) { const a = xs[0]; return a.toFixed(2); } // expect TS18048

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { label, firstTag } from '../src/rules.ts';
test('label', () => { assert.equal(label('VLOG'), 'Vlog'); assert.equal(label('CODE_REVIEW'), 'Review'); });
test('firstTag', () => { assert.equal(firstTag(['be']), 'BE'); assert.equal(firstTag([]), ''); });

